  "creator.dmHint.ai": "L'IA raconte, tranche et fait vivre le monde. Le chef du groupe la guide.",
  "creator.dmHint.steered": "L'IA raconte chaque tour. Tu es derrière l'écran avec l'intrigue, la console et le dernier mot, et tu ne joues aucun personnage.",
  "creator.dmHint.human": "Tu racontes. Le serveur fait quand même respecter chaque règle et lance chaque dé.",
  "creator.dmHint.assisted": "L'histoire t'appartient ; confie à l'IA les monstres, la prose ou une suite de tours.",
