  "builder.ancestry.chooseLanguage": "Choisis une langue...",
  "builder.ancestry.languagesInfo":
    "Une langue que tu connais est une langue que tu parles, lis et écris. Elle décide à qui ton personnage peut parler sans aide, et elle compte plus qu'un nouveau joueur ne l'attend : la moitié des ennuis d'un donjon sont écrits sur un mur.\n\nLe commun est la langue du commerce que tout le monde partage. Les autres sont les langues de peuples précis : nain, elfe, orc, draconique et ainsi de suite. Choisis ce qui colle à l'endroit où ton personnage a grandi, ou à qui tu comptes négocier.",
