  // Le mode d'emploi (HowToPlayDialog.tsx). Le titre du dialogue et les
  // pastilles des modes reprennent home.howToPlay et table.composer.mode.*.
  // Les morceaux coupés par un mot en surbrillance sont des paires
  // _before/_after autour du passage allumé.
  "help.howToPlay.what.title": "Ce qu'est cette appli",
  "help.howToPlay.what.p1": "Open Game Master est une table de Dungeons & Dragons 5e où une IA s'assoit dans le fauteuil du maître du jeu, ou bien un ami s'y assoit avec l'IA comme assistante. Toi et tes amis jouez les aventuriers. L'appli, c'est le livre de règles et les dés.",
  "help.howToPlay.what.p2": "Chaque table tourne avec les règles du 5e. Le décor, c'est toi qui le choisis : un genre à ton goût, ou l'un des mondes tout prêts installés sur ton serveur.",
  "help.howToPlay.started.title": "Bien commencer",
  "help.howToPlay.started.p1Span": "Nouvelle campagne",
  "help.howToPlay.started.p1After": " crée le monde : choisis un genre, une difficulté et un niveau de départ, et donne au MJ, si tu veux, une mise en place secrète que lui seul connaîtra. Si le serveur a des plugins de campagne installés, tu peux y choisir un monde tout prêt plutôt qu'un simple genre, ce qui apporte ses races, classes, monstres et son lore sans rien changer aux règles. Tu reçois un code d'invitation de huit lettres à partager avec tes amis.",
  "help.howToPlay.started.p2Span": "Aventure solo",
  "help.howToPlay.started.p2Mid": " est la même chose pour un joueur seul. Pour rejoindre la table de quelqu'un d'autre, colle son code dans « ",
  "help.howToPlay.started.p2Tail": " » ou ouvre le lien d'invitation qu'il t'envoie.",
  "help.howToPlay.started.p3": "Crée ensuite un personnage dans l'assistant de création, ou reprends-en un rangé sous Personnages dans le menu du compte. Tout le monde se tient prêt dans le salon, et le propriétaire de la campagne lance l'aventure.",
  "help.howToPlay.run.title": "Comment la partie est menée",
  "help.howToPlay.run.p1": "L'appli fait tous les calculs et donne le résultat au MJ, qui le tisse dans l'histoire. Jets d'attaque, dégâts, jets de sauvegarde, jets de mort, états, emplacements de sorts, repos, XP et montées de niveau sont tous résolus par le serveur selon les règles du 5e et écrits directement sur ta fiche de personnage.",
  "help.howToPlay.run.p2": "Le MJ raconte ce que ces résultats veulent dire. Il ne peut ni inventer un jet ni te glisser en douce un bonus : joue l'histoire plutôt que de disputer les chiffres. Chaque jet et chaque changement de caractéristique est consigné au journal, sous l'onglet Histoire, si tu veux vérifier les calculs.",
  "help.howToPlay.turn.title": "Jouer son tour",
  "help.howToPlay.turn.intro": "Les boutons au-dessus de la messagerie changent ce que ton message veut dire :",
  "help.howToPlay.turn.do": "Décris ce que fait ton personnage. Le MJ raconte le résultat et demande un jet quand les règles le demandent.",
  "help.howToPlay.turn.say": "Parle comme ton personnage. Ton texte part en dialogue parlé.",
  "help.howToPlay.turn.ooc": "Discussion de table hors-personnage. Le MJ ne la lit pas et ne répond pas.",
  "help.howToPlay.turn.askBefore": "Pour poser au MJ une question sur l'histoire, le monde, les règles ou ta fiche, ouvre le bandeau ",
  "help.howToPlay.turn.askAfter": " juste au-dessus de la messagerie. La réponse cite ce que la campagne a enregistré, et tu choisis si elle reste pour toi ou s'ouvre à toute la table. Demander ne fait jamais avancer l'histoire, donc ça marche même quand la parole est retenue.",
  "help.howToPlay.wait.title": "Un tour à la fois",
  "help.howToPlay.wait.p1": "Quand le MJ se met à réfléchir, il lit tout ce qui a été envoyé jusque-là et écrit une seule réponse pour toute la table. Ce que tu envoies pendant qu'il réfléchit encore ne changera pas cette réponse. Ce sera repris au prochain tour, avec ce que les autres ont envoyé.",
  "help.howToPlay.wait.p2Before": "Alors si tu joues avec d'autres, ",
  "help.howToPlay.wait.p2Span": "discutez vos options avant que quelqu'un envoie, puis envoyez chacun une action claire",
  "help.howToPlay.wait.p2After": ". Empiler les messages pendant la narration ne presse pas le MJ et ne détourne pas la réponse déjà en cours.",
  "help.howToPlay.wait.p3": "Le HRP est le canal sûr pour cette discussion : il ne réveille jamais le MJ, et il passe même quand la parole est retenue pendant la narration. Parfois le MJ place un joueur sous le feu des projecteurs et l'attend ; un bandeau te dira quand c'est la raison pour laquelle tu ne peux pas agir.",
  "help.howToPlay.re.title": "Quand une réponse tombe mal",
  "help.howToPlay.re.p1Before": "Rien de ce qu'écrit le MJ n'est définitif. Survole l'un de ses messages : une rangée d'actions apparaît. Le chef de groupe peut le faire ",
  "help.howToPlay.re.reroll": "relancer",
  "help.howToPlay.re.p1Mid": " sur ce moment, mêmes dés et même résultat, seule la formulation change, puis feuilleter les versions et laisser la meilleure sous les yeux de la table. Il peut aussi la faire ",
  "help.howToPlay.re.continue": "continuer",
  "help.howToPlay.re.p1After": " quand une réponse s'est arrêtée en chemin, ou en corriger la formulation à la main.",
  "help.howToPlay.re.p2": "Deux de ces actions sont ouvertes à tout le monde. Chacun peut confronter un passage à ce que la campagne a déjà établi, et chacun peut sélectionner une ligne et presser l'épingle pour garder ce détail sous les yeux du MJ pour le reste de la campagne.",
  "help.howToPlay.stuck.title": "Si tu es bloqué",
  "help.howToPlay.stuck.p1": "L'entrée Aide, dans le menu du compte ici comme dans l'en-tête pendant une session, passe en revue chaque bouton et chaque panneau : les onglets du panneau latéral, le bandeau Ask, les actions sur chaque message, les options de dés, la voix de la narration, les notes, les chuchotements, les packs de monde et les pouvoirs du chef de groupe. Si un projecteur bloque la table, le chef de groupe peut le lever.",
  // Les amis : le cercle social du serveur (src/app/friends/page.tsx).
