  "admin.worlds.clearFilter": "Effacer le filtre",
  "admin.worlds.intro": "Un pack de monde renomme les règles dans un cadre : ses propres races, classes, sorts, équipements, monstres, factions et lore, plus un court texte qui dit au MJ comment ce monde sonne. Chaque mécanique reste du 5e, donc un personnage créé dans l'un marche partout.",
  "admin.worlds.disclaimer": "Les packs bâtis sur un univers existant sont des œuvres communautaires. Ils ne sont pas distribués avec Open Game Master, ne sont pas couverts par sa licence MIT, et ne sont pas approuvés par les ayants droit des cadres qu'ils référencent. En installer un est ta décision, en tant qu'opérateur de ce serveur.",
  "admin.worlds.makeOwn": "Fabrique le tien dans l'outil Plugin d'un atelier, ou depuis un monde bâti dans WorldForge : ",
