  "admin.backup.loadAria": "Chargement des sauvegardes",
  "admin.backup.intro": "Une sauvegarde met la base de campagnes chiffrée, les envois, les médias générés et les réglages du serveur dans une seule archive. Les modèles téléchargés en sont exclus sauf si tu les inclus ; ils se retéléchargent au premier usage. L'archive porte la clé de chiffrement de la base, donc garde-la comme un mot de passe : qui la tient peut lire chaque campagne. ",
