  "admin.usage.kind.workshop": "atelier",
  "admin.usage.kind.playtest": "combat d'essai",
  "admin.usage.accountsNote": "Campagnes : possédées / menées / rejointes. Ce qu'une campagne dépense est compté à son chef de groupe, comme le réglage d'IA payante le décide par le chef ; le stockage est celui des personnages du compte plus les campagnes qu'il possède.",
  "admin.usage.campaignsNote": "Les jours actifs sont les jours avec au moins un tour du MJ, ce qui compte du jeu plutôt que des heures. Le stockage est celui de chaque image et fichier nommé par les lignes de la campagne, copies redimensionnées comprises.",
  "admin.usage.modelCalls": "Appels aux modèles, 7 derniers jours",
  "admin.usage.th.for": "Pour",
  "admin.usage.th.calls": "Appels",
  "admin.usage.th.failed": "Échecs",
  "admin.usage.th.fellBack": "Repliés",
  "admin.usage.th.median": "Médiane",
  "admin.usage.th.p95": "95e",
  "admin.usage.th.firstWords": "Premiers mots",
  "admin.usage.th.input": "Entrée",
  "admin.usage.th.cached": "En cache",
  "admin.usage.th.output": "Sortie",
  "admin.usage.th.reasoning": "Raisonnement",
  "admin.usage.modelCallsNote": "Une ligne par sorte d'appel : les tours du MJ, le lecteur, les résumés, Ask et le reste. Les temps sont des médianes et le 95e centile ; entrée, sortie et raisonnement sont des moyennes de ce que les backends ont déclaré ; « en cache » est la part d'entrée qu'un backend dit avoir servie de son cache de prompt, là où il le dit. Un tiret est un chiffre qu'aucun backend n'a rapporté. Conservé 30 jours, sans texte de prompt ni de réponse.",
  "admin.usage.tokens": "{in} envoyés / {out} reçus",
  "admin.usage.paid": "{count} payants",
