  "narrator.noService": "Ce serveur n'a pas encore de service de voix, donc rien n'est lu à voix haute. Demande à celui qui tient le serveur d'en installer un ; la campagne pourra activer la narration depuis ses Réglages de table ensuite.",
  "narrator.voiceLabel": "Voix du narrateur",
  "narrator.pace": "Cadence",
  "narrator.paceLabel": "Cadence du narrateur",
  "narrator.whoLabel": "Voix des personnages",
  "narrator.whoTitle": "Qui prête sa voix aux personnages ?",
  "narrator.readThem": "Le narrateur les lit",
  "narrator.readThemHint": "Jusqu'à ce que tu donnes à un personnage une voix à lui",
  "narrator.eachVoice": "Chaque parole a sa voix",
  "narrator.eachVoiceHint": "Choisie parmi les voix de ce serveur à la première prise de parole, puis gardée",
  "narrator.eachNote": "Quiconque parle reçoit une voix la première fois et la garde. ",
  "narrator.readNote": "Ceux qui n'ont pas de voix à eux sont lus par le narrateur. ",
  "narrator.changeLater": "Change la voix de n'importe quel personnage plus tard dans {place}.",
  "narrator.offNote": "La narration est coupée, donc rien n'est lu à voix haute. Les choix de narrateur et de voix des personnages sont gardés pour la remettre.",
  "narrator.allies": "Alliés IA",
  "narrator.alliesSolo": "Les membres du groupe voyagent avec toi jusqu'à ce que tu les renvoies ; les invités sont des alliés qui arrivent pour une scène ou un combat puis s'en vont.",
  "narrator.alliesTable": "Les invités sont des PNJ amicaux que le MJ amène pour une scène ou un combat ; ils se battent avec de vraies stats et repartent à la fin. Les membres du groupe restent jusqu'à ce que tu les renvoies.",
  "narrator.partyAtOnce": "Membres du groupe à la fois",
  "narrator.guestsAtOnce": "Invités à la fois",
  "creator.info.casting": "Deux choix décident qui lit une réplique à voix haute.\n\n**La voix et la cadence du narrateur** lisent l'histoire, et toute parole qui n'a pas de voix à elle.\n\n**Les voix des personnages** appartiennent à un locuteur chacune. Avec *Chaque parole a sa voix*, quiconque parle (un aubergiste, un monstre, un compagnon) reçoit une des voix de ce serveur à sa première réplique et la garde ensuite. Avec *Le narrateur les lit*, personne n'en reçoit automatiquement, et toute voix que tu donnes quand même à un personnage reste jouée.\n\nDans tous les cas, une voix se donne ou se change par personnage une fois la campagne peuplée : la liste Voix des personnages dans les Réglages de la table (Narration et voix des personnages), dans le salon ou l'onglet Réglages de la table. Chaque joueur peut aussi y choisir la voix de son propre personnage.\n\nCeci est la narration parlée de la table. La voix en direct entre joueurs est un réglage à part.",
  "creator.casting.place": "la liste Voix des personnages dans les Réglages de la table (Narration et voix des personnages), dans le salon ou l'onglet Réglages de la table",

