  "admin.voice.heading": "Chat vocal",
  "admin.voice.intro.a": "Laisse une table se parler en audio en direct. Demande deux choses en plus de cet interrupteur : l'appli jointe en ",
  "admin.voice.intro.b": " (les navigateurs bloquent le micro en http simple, sauf sur localhost), et ",
  "admin.voice.intro.port": "un port ouvert",
  "admin.voice.intro.c": " en UDP comme en TCP. Ce port porte l'audio lui-même, qui n'est pas du HTTP et ne passe pas par un reverse proxy, donc ouvre-le sur ton pare-feu directement vers cet hôte.",
