  "admin.voice.transportHint": "Le serveur vocal demande le port média ci-dessous ouvert. Le pair-à-pair n'a pas besoin de port et passe par les tunnels, mais convient aux petites tables : chaque joueur envoie l'audio à tous les autres.",
