  "admin.voice.announced": "Adresse annoncée",
  "admin.voice.announcedHint": "L'adresse à laquelle le NAVIGATEUR d'un joueur peut joindre cet hôte, en général ton IP publique. Ne la laisse vide que pour une installation réservée à localhost.",
  "admin.voice.domain": "Domaine vocal (facultatif)",
  "admin.voice.domainHint": "Annonce un nom d'hôte au lieu de l'IP. Il doit résoudre directement ici : un nom proxifié par Cloudflare ne porte pas l'UDP, donc les appels connecteraient et resteraient muets.",
  "admin.voice.unroutable": "Le vocal connectera mais restera muet pour les joueurs à distance : pose une adresse ou un domaine annoncé.",
  "admin.voice.applyNote": "Les changements de port et d'adresse s'appliquent à la prochaine fois que quelqu'un rejoint un appel, une fois que personne n'est connecté. Pas de redémarrage du serveur nécessaire.",
  "admin.discord.heading": "Connexion Discord",
  "admin.discord.intro.a": "Facultatif. Crée une application sur discord.com/developers, ajoute l'URI de redirection ",
  "admin.discord.intro.b": " (l'adresse exacte qu'utilisent les joueurs, p. ex. https://ton.domaine ou http://hote-lan:3005), puis colle l'ID client et le secret. Le bouton de connexion paraît dès que les deux sont posés. Derrière un reverse proxy, règle aussi l'URL publique dans la section Serveur ci-dessus.",
  "admin.discord.clientId": "ID client",
  "admin.discord.clientSecret": "Secret client",
  "admin.discord.secretEnv": "Un secret de variable d'environnement est aussi posé.",
  "admin.discord.notSet": "Pas posé",
  "admin.playerAgents.loadAria": "Chargement des adresses de réception",
  "admin.playerAgents.intro": "Un joueur peut asseoir son propre agent à une table et le faire réveiller à son tour par un petit récepteur sur son ordinateur (Réglages > Agents connectés). Ce serveur n'envoie qu'aux adresses HTTPS listées ici. N'en ajoute que pour un récepteur auquel tu fais confiance : il permet au serveur de faire des requêtes vers cet hôte.",
  "admin.playerAgents.none": "Aucune adresse de réception pour l'instant, donc aucun agent de joueur ne reçoit de webhook.",
  "admin.playerAgents.fromEnv": "de ODM_PLAYER_WEBHOOK_ORIGINS",
  "admin.playerAgents.address": "Adresse de réception",
  "admin.playerAgents.allow": "Autoriser",
  "admin.playerAgents.poll": "Autoriser les liens de sondage",
  "admin.playerAgents.pollHint": "Pour un agent vers lequel rien ne peut envoyer de requêtes (un assistant hébergé dont les hooks ne savent que consulter une URL) : son joueur reçoit un lien secret qui dit quand son personnage a quelque chose à faire. Le serveur n'envoie rien ; quiconque tient le lien peut voir cela. Ça s'arrête quand le joueur le remplace, le retire ou révoque la connexion. Désactiver ceci supprime chaque lien.",
  "admin.playerAgents.saveFailed": "Impossible d'enregistrer les réglages des agents des joueurs.",
  "admin.storage.loadAria": "Chargement du stockage",
  "admin.storage.intro": "L'histoire est gardée pour toujours : chaque message, jet, note, fiche, instantané de chapitre et conversation du MJ. Une fois par jour, le serveur efface ce que plus rien ne relit (les mises à jour en direct plus vieilles que ce qu'une page qui se reconnecte rejoue, les traces de prompts de plus d'une semaine, les lignes d'usage de plus de 90 jours fusionnées par mois à totaux égaux) et rend la place au disque.",
