  "admin.storage.compact": "Compacter la base",
  "admin.storage.compactConfirm": "Compacter la base ? Elle est réécrite sans son espace libre, et le jeu se met en pause pendant l'opération : une seconde ou deux pour la plupart des serveurs. Ensuite, le nettoyage quotidien rend l'espace libéré de lui-même.",
