  "rulebook.frontis.text1": "Chaque règle du jeu en un seul volume : les races et les classes, l'équipement, l'usage des scores de caractéristique, l'aventure, le combat, la magie, tous les sorts, objets magiques et monstres, et les états qu'ils infligent.",
  "rulebook.frontis.text2": "Trois livres sont reliés ici : celui des joueurs, celui du maître du jeu et celui des monstres, tenant chacun tout ce que le document de référence ouvre du Player's Handbook, du Dungeon Master's Guide et du Monster Manual.",
  "rulebook.frontis.text3": "Cherche depuis le sommaire, ou ouvre un chapitre. Les flèches tournent les pages, et un marque-page garde une page à une touche d'ici.",
