// ---- les groupes du sélecteur d'options (usePickerGroups.ts) ----
  "builder.group.align.info":
    "L'alignement est un raccourci de deux mots pour la façon dont ton personnage traite les règles (loyal, neutre, chaotique) et les autres (bon, neutre, mauvais). Il n'oblige à rien : c'est une note pour toi et pour le MJ sur la façon dont cette personne a tendance à agir, et les personnages dérivent au fil d'une campagne. Choisis celui qui lui ressemble le plus et n'y pense plus.",
  "builder.group.align.LG": "Loyal bon",
  "builder.group.align.NG": "Neutre bon",
  "builder.group.align.CG": "Chaotique bon",
  "builder.group.align.LN": "Loyal neutre",
  "builder.group.align.N": "Neutre strict",
  "builder.group.align.CN": "Chaotique neutre",
  "builder.group.align.LE": "Loyal mauvais",
  "builder.group.align.NE": "Neutre mauvais",
  "builder.group.align.CE": "Chaotique mauvais",
  "builder.group.align.LG.blurb": "Fait ce qui est juste, selon les règles. Tient ses promesses, protège les faibles, fait confiance aux institutions quand elles méritent d'être défendues. Le choix par défaut du paladin.",
  "builder.group.align.NG.blurb": "Fait le plus de bien possible, loi ou pas loi. Aide celui qui est devant lui sans trop compter ce qu'on lui doit.",
  "builder.group.align.CG.blurb": "Fait ce qui est juste, et brise la règle qui le gêne. Rebels, contrebandiers avec une conscience, gens qui libèrent les prisonniers d'abord et demandent ensuite.",
  "builder.group.align.LN.blurb": "L'ordre pour lui-même. Le juge, le soldat, le moine : le code compte plus qu'aucun résultat qu'il produit.",
  "builder.group.align.N.blurb": "Aucun penchant marqué dans un sens ou l'autre. Vit sa vie, choisit son camp quand il faut en choisir un. L'alignement le plus courant des gens ordinaires.",
  "builder.group.align.CN.blurb": "La liberté avant tout, surtout la sienne. Imprévisible mais pas cruel. Facile à mal jouer ; parles-en à ta table avant de le choisir.",
  "builder.group.align.LE.blurb": "Prend ce qu'il veut, dans un système qu'il respecte et utilise. Tyrans, fonctionnaires corrompus, diables. Tient parole, ce qui le rend pire.",
  "builder.group.align.NE.blurb": "Prend ce qu'il veut sans se soucier de l'emballer. N'est loyal qu'envers lui-même.",
  "builder.group.align.CE.blurb": "La destruction pour elle-même. Presque toujours un alignement de PNJ ; un groupe y survit rarement.",
  "builder.group.commonIn": "Courants chez : {pack}",
  "builder.group.peoplesOf": "Peuples de {pack}",
  "builder.group.callingsOf": "Voies de {pack}",
  "builder.group.livesIn": "Vies de {pack}",
  "builder.group.allAlignments": "Tous les alignements",
  "builder.group.allRaces": "Toutes les races",
